function refreshChips(){chips('numbers',['1','2','3','4','5','6','Más de 6'],number,x=>number=x);chips('weapons',['Desarmado','Pistola','Escopeta','Navaja','Pincho','No se distingue'],weapon,x=>weapon=x);renderTravelButtons();}
function clearConfig(){number='';weapon='';vehicle=null;for(const id of configFields)$(id).value='';document.querySelectorAll('#details input').forEach(c=>c.checked=false);$('search').value='';$('category').value='';onlyFav=false;$('favfilter').setAttribute('aria-pressed','false');$('favfilter').textContent='☆ Favoritos';$('garage').hidden=true;refreshChips();renderCars();generate();$('status').textContent='';}
$('reset').textContent='Vaciar todo ↻';$('reset').onclick=clearConfig;
let slots=Array(5).fill(null);try{const saved=JSON.parse(localStorage.getItem('entorno-configs-v1')||'null');if(Array.isArray(saved))slots=Array.from({length:5},(_,i)=>saved[i]&&typeof saved[i]==='object'?saved[i]:null);}catch{}
function persistSlots(next){try{localStorage.setItem('entorno-configs-v1',JSON.stringify(next));slots=next;return true}catch{$('slot-status').textContent='No se ha podido guardar. Revisa el almacenamiento del navegador.';return false}}
function snapshot(){return {fields:Object.fromEntries(configFields.map(id=>[id,$(id).value])),number,weapon,vehicleId:vehicle?.id||null,details:[...document.querySelectorAll('#details input:checked')].map(c=>c.value)}}
function loadConfig(data){clearConfig();for(const id of configFields){if(typeof data.fields?.[id]==='string')$(id).value=data.fields[id];}number=['1','2','3','4','5','6','Más de 6'].includes(data.number)?data.number:'';weapon=['Desarmado','Pistola','Escopeta','Navaja','Pincho','No se distingue'].includes(data.weapon)?data.weapon:'';vehicle=catalog.find(c=>c.id===data.vehicleId)||null;document.querySelectorAll('#details input').forEach(c=>c.checked=Array.isArray(data.details)&&data.details.includes(c.value));$('garage').hidden=$('travel').value!=='vehicle';refreshChips();renderCars();generate();}
let activeSlot=0;
function renderSlots(){const wrap=$('slots');wrap.replaceChildren();const row=document.createElement('div');row.className='slot';const select=document.createElement('select');select.setAttribute('aria-label','Espacio de configuración');slots.forEach((slot,i)=>{const o=document.createElement('option');o.value=i;o.textContent=(i+1)+' · '+(slot?.name||'Vacío');select.append(o)});select.value=activeSlot;select.onchange=()=>{activeSlot=+select.value;renderSlots();$('slot-status').textContent=''};const slot=slots[activeSlot];const name=document.createElement('input');name.maxLength=40;name.placeholder='Nombre';name.value=slot?.name||'';name.setAttribute('aria-label','Nombre de configuración');const save=document.createElement('button');save.type='button';save.textContent=slot?'Actualizar':'Guardar';save.onclick=()=>{const next=slots.slice();next[activeSlot]={name:name.value.trim()||'Configuración '+(activeSlot+1),data:snapshot()};if(persistSlots(next)){renderSlots();$('slot-status').textContent='Configuración guardada.'}};const load=document.createElement('button');load.type='button';load.textContent='Cargar';load.disabled=!slot;load.onclick=()=>{loadConfig(slot.data||{});$('slot-status').textContent='Cargada: '+slot.name};const del=document.createElement('button');del.type='button';del.textContent='×';del.setAttribute('aria-label','Borrar configuración seleccionada');del.title='Borrar configuración';del.disabled=!slot;del.onclick=()=>{const next=slots.slice();next[activeSlot]=null;if(persistSlots(next)){renderSlots();$('slot-status').textContent='Espacio vacío.'}};row.append(select,name,save,load,del);wrap.append(row);}

clearConfig();renderSlots();
